import{_ as a,o as n,c as p,a2 as e}from"./chunks/framework.DYYBR_aZ.js";const k=JSON.parse('{"title":"Redis 分布式锁：从 SET NX EX 到 Redisson RLock","description":"","frontmatter":{},"headers":[],"relativePath":"java/Redis 分布式锁：从 SET NX EX 到 Redisson RLock.md","filePath":"java/Redis 分布式锁：从 SET NX EX 到 Redisson RLock.md"}'),i={name:"java/Redis 分布式锁：从 SET NX EX 到 Redisson RLock.md"};function l(o,s,t,c,d,h){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="redis-分布式锁-从-set-nx-ex-到-redisson-rlock" tabindex="-1">Redis 分布式锁：从 SET NX EX 到 Redisson RLock <a class="header-anchor" href="#redis-分布式锁-从-set-nx-ex-到-redisson-rlock" aria-label="Permalink to &quot;Redis 分布式锁：从 SET NX EX 到 Redisson RLock&quot;">​</a></h1><h2 id="一、为什么需要分布式锁" tabindex="-1">一、为什么需要分布式锁？ <a class="header-anchor" href="#一、为什么需要分布式锁" aria-label="Permalink to &quot;一、为什么需要分布式锁？&quot;">​</a></h2><p>在 Java 开发中，我们经常使用 <code>synchronized</code> 或 <code>ReentrantLock</code> 控制多线程对共享资源的访问，避免多个线程同时修改数据，造成并发问题。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public synchronized void updateStock() {</span></span>
<span class="line"><span>    // 修改库存</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这类锁主要解决的是同一个 JVM 进程内部的线程竞争问题。</p><p>但在实际的企业级应用中，一个 Java 服务往往会部署多个实例。例如，为了提高系统的并发处理能力，我们可能部署三个 Spring Boot 实例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  Nginx</span></span>
<span class="line"><span>                    |</span></span>
<span class="line"><span>          +---------+---------+</span></span>
<span class="line"><span>          |         |         |</span></span>
<span class="line"><span>       实例 A     实例 B     实例 C</span></span>
<span class="line"><span>       JVM 1     JVM 2     JVM 3</span></span>
<span class="line"><span>          |         |         |</span></span>
<span class="line"><span>          +---------+---------+</span></span>
<span class="line"><span>                    |</span></span>
<span class="line"><span>                 MySQL</span></span></code></pre></div><p>这三个实例拥有各自独立的 JVM 内存，因此各自的 <code>synchronized</code> 锁无法自动协调其他实例中的线程。</p><p>假设三个实例同时收到一个请求，都需要重建同一个优惠券模板的缓存，那么它们可能同时查询 MySQL、同时构建缓存。</p><p>此时，单机锁已经无法满足需求。</p><p>我们需要一种能够被多个应用实例共同访问和协调的锁机制，这就是<strong>分布式锁</strong>。</p><p>分布式锁的核心思想是：将锁的状态保存在多个应用实例都能访问的共享资源中，让不同实例通过竞争同一把锁，实现跨进程的互斥访问。</p><p>Redis 是实现分布式锁的一种常见方案。</p><h2 id="二、redis-为什么能够实现分布式锁" tabindex="-1">二、Redis 为什么能够实现分布式锁？ <a class="header-anchor" href="#二、redis-为什么能够实现分布式锁" aria-label="Permalink to &quot;二、Redis 为什么能够实现分布式锁？&quot;">​</a></h2><h3 id="_1-redis-提供共享的存储空间" tabindex="-1">1. Redis 提供共享的存储空间 <a class="header-anchor" href="#_1-redis-提供共享的存储空间" aria-label="Permalink to &quot;1. Redis 提供共享的存储空间&quot;">​</a></h3><p>Redis 通常作为一个独立的中间件运行，不论是同一台机器上的多个 JVM，还是部署在不同服务器上的应用实例，都可以连接同一个 Redis 服务。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       Spring Boot 实例 A</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>       Spring Boot 实例 B</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>       Spring Boot 实例 C</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>                v</span></span>
<span class="line"><span>          Redis Server</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>       lock:coupon:1001</span></span></code></pre></div><p>三个应用实例都可以访问 Redis 中的 <code>lock:coupon:1001</code>。</p><p>因此，锁的状态不再保存在某个 JVM 的内存中，而是保存在多个实例共享的 Redis 中。</p><h3 id="_2-redis-的原子操作保证锁竞争的互斥性" tabindex="-1">2. Redis 的原子操作保证锁竞争的互斥性 <a class="header-anchor" href="#_2-redis-的原子操作保证锁竞争的互斥性" aria-label="Permalink to &quot;2. Redis 的原子操作保证锁竞争的互斥性&quot;">​</a></h3><p>Redis 的核心命令执行具有串行化语义。多个客户端同时执行普通命令时，Redis 会按照执行顺序处理它们。</p><p>我们可以利用这一特性，通过 <code>SET NX EX</code> 命令实现最基本的分布式锁。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET lock:coupon:1001 unique-token NX EX 30</span></span></code></pre></div><p>这条命令包含三个部分：</p><table tabindex="0"><thead><tr><th>参数</th><th>含义</th></tr></thead><tbody><tr><td>SET</td><td>设置 Key 的值</td></tr><tr><td>NX</td><td>只有 Key 不存在时才设置成功</td></tr><tr><td>EX 30</td><td>设置 30 秒过期时间</td></tr></tbody></table><p>假设三个应用实例同时竞争这把锁：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实例 A：SET lock:coupon:1001 token-A NX EX 30</span></span>
<span class="line"><span>实例 B：SET lock:coupon:1001 token-B NX EX 30</span></span>
<span class="line"><span>实例 C：SET lock:coupon:1001 token-C NX EX 30</span></span></code></pre></div><p>Redis 依次处理这些命令。</p><ol><li>实例 A 首先执行，发现 Key 不存在，于是创建锁记录，返回 OK。</li><li>实例 B 执行时，发现 Key 已经存在，设置失败。</li><li>实例 C 执行时，同样发现 Key 已经存在，设置失败。</li></ol><p>最终只有实例 A 成功获得锁。</p><p>这里最关键的是：<code>SET</code>、<code>NX</code> 和 <code>EX</code> 被组合成一条 Redis 命令，判断 Key 是否存在、设置锁记录和设置过期时间作为一个原子操作完成，不会出现先判断、再设置时被其他请求插入的竞态问题。</p><p>因此，Redis 提供的原子操作就成为实现分布式锁的基础。</p><p><strong>需要注意，Redis 并不是因为所有操作都由单线程执行才天然具有分布式锁能力，而是因为它能够提供满足互斥要求的原子操作。</strong></p><h3 id="_3-为什么还需要设置过期时间" tabindex="-1">3. 为什么还需要设置过期时间？ <a class="header-anchor" href="#_3-为什么还需要设置过期时间" aria-label="Permalink to &quot;3. 为什么还需要设置过期时间？&quot;">​</a></h3><p>假设实例 A 成功获取锁后，突然发生宕机：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实例 A 获取锁成功</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>Redis 中存在 lock:coupon:1001</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>实例 A 突然宕机</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>没有机会主动释放锁</span></span></code></pre></div><p>如果锁一直存在，其他实例就可能永远无法获得锁，形成死锁。</p><p>因此，使用 <code>EX 30</code> 设置过期时间，能够让锁在一定时间后自动释放。</p><p>不过，固定过期时间也有风险：如果业务执行时间超过 30 秒，锁已经过期，但原来的业务线程可能还在执行。其他实例此时就可能获得同一把锁，造成两个线程同时操作共享资源。</p><p>因此，实际工程中的分布式锁还需要考虑锁续期、锁释放和持有者身份校验等问题。</p><h2 id="三、为什么需要-redisson" tabindex="-1">三、为什么需要 Redisson？ <a class="header-anchor" href="#三、为什么需要-redisson" aria-label="Permalink to &quot;三、为什么需要 Redisson？&quot;">​</a></h2><p>虽然我们可以通过 <code>SET NX EX</code> 实现基本的分布式锁，但如果每次都自己编写锁的获取、释放和续期逻辑，会增加开发成本，也容易出现并发安全问题。</p><p>例如：</p><ul><li>如何判断当前线程是否已经持有锁？</li><li>如何实现可重入？</li><li>获取锁失败后如何等待？</li><li>如何避免错误释放其他线程持有的锁？</li><li>如果业务执行时间超过预设时间，如何续期？</li><li>锁释放后，如何通知其他等待者？</li></ul><p>Redisson 就是为此提供了更高级的 Redis Java 客户端能力。</p><p>它不仅封装了 Redis 的基本数据结构，还提供了分布式锁、阻塞队列、延迟队列等功能。</p><p>其中，<code>RLock</code> 就是 Redisson 提供的分布式可重入锁。</p><h2 id="四、redisson-的分布式锁-api" tabindex="-1">四、Redisson 的分布式锁 API <a class="header-anchor" href="#四、redisson-的分布式锁-api" aria-label="Permalink to &quot;四、Redisson 的分布式锁 API&quot;">​</a></h2><p>先看实际项目中的代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RLock lock = redissonClient.getLock(</span></span>
<span class="line"><span>        String.format(</span></span>
<span class="line"><span>                EngineRedisConstant.LOCK_COUPON_TEMPLATE_KEY,</span></span>
<span class="line"><span>                requestParam.getCouponTemplateId()</span></span>
<span class="line"><span>        )</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>lock.lock();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>try {</span></span>
<span class="line"><span>    // 执行业务逻辑</span></span>
<span class="line"><span>} finally {</span></span>
<span class="line"><span>    lock.unlock();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这段代码看起来很简单，但涉及几个重要的 API。</p><h3 id="_1-redissonclient-redisson-的客户端入口" tabindex="-1">1. RedissonClient：Redisson 的客户端入口 <a class="header-anchor" href="#_1-redissonclient-redisson-的客户端入口" aria-label="Permalink to &quot;1. RedissonClient：Redisson 的客户端入口&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>private final RedissonClient redissonClient;</span></span></code></pre></div><p><code>RedissonClient</code> 是 Redisson 提供的客户端接口，可以理解为 Java 应用访问 Redis 的入口。</p><p>在 Spring Boot 项目中，通常通过配置文件配置 Redis 连接信息，再通过 Redisson 自动配置或自定义配置创建客户端 Bean，最后通过构造器注入业务类。</p><p>例如：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RequiredArgsConstructor</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Service</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CouponTemplateServiceImpl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> final</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RedissonClient redissonClient;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这里使用 Lombok 的 <code>@RequiredArgsConstructor</code>，为 <code>final</code> 字段生成构造方法，Spring 通过构造器完成依赖注入。</p><p>因此，我们不需要在业务代码中手动创建 Redisson 客户端，就可以直接使用它。</p><h3 id="_2-getlock-获取分布式锁对象" tabindex="-1">2. getLock()：获取分布式锁对象 <a class="header-anchor" href="#_2-getlock-获取分布式锁对象" aria-label="Permalink to &quot;2. getLock()：获取分布式锁对象&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RLock lock = redissonClient.getLock(&quot;my-lock&quot;);</span></span></code></pre></div><p>这里的 <code>getLock()</code> 用于根据锁名称获取一个 <code>RLock</code> 对象。</p><p>需要注意：<strong>调用</strong> <code>**getLock()**</code> <strong>并不意味着已经成功获取锁。</strong></p><p>它只是获取一个代表 Redis 分布式锁的 Java 操作对象，真正的锁竞争发生在调用 <code>lock()</code> 或 <code>tryLock()</code> 时。</p><p>锁名称非常重要，因为它决定了不同请求是否在竞争同一把锁。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>redissonClient.getLock(&quot;coupon:1001&quot;);</span></span>
<span class="line"><span>redissonClient.getLock(&quot;coupon:1002&quot;);</span></span></code></pre></div><p>这两把锁对应不同的 Redis Key，因此不同优惠券模板的缓存重建可以并行执行。</p><p>而多个实例如果都使用 <code>coupon:1001</code>，就会竞争同一把逻辑锁。</p><h3 id="_3-lock-阻塞式获取锁" tabindex="-1">3. lock()：阻塞式获取锁 <a class="header-anchor" href="#_3-lock-阻塞式获取锁" aria-label="Permalink to &quot;3. lock()：阻塞式获取锁&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lock.lock();</span></span></code></pre></div><p>调用 <code>lock()</code> 后，当前线程会尝试获取锁。</p><p>如果锁没有被其他线程持有，就可以直接获取成功；如果已经被其他线程持有，当前线程通常会等待，直到能够获得锁。</p><p>这里的等待并不意味着一直向 Redis 发送请求进行高频轮询。</p><p>Redisson 的常规 <code>RLock</code> 实现会结合 Redis Pub/Sub 发布订阅机制：竞争失败的线程订阅锁对应的通知频道，在锁释放时收到通知，再重新尝试获取锁。必要时也会根据锁的剩余有效时间进行等待和再次尝试。</p><p>因此，Redisson 不只是简单地封装了一条 <code>SET NX EX</code> 命令，而是实现了更完整的锁竞争与等待机制。</p><h3 id="_4-trylock-尝试获取锁" tabindex="-1">4. tryLock()：尝试获取锁 <a class="header-anchor" href="#_4-trylock-尝试获取锁" aria-label="Permalink to &quot;4. tryLock()：尝试获取锁&quot;">​</a></h3><p>除了 <code>lock()</code>，Redisson 还提供了 <code>tryLock()</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>boolean success = lock.tryLock();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if (success) {</span></span>
<span class="line"><span>    try {</span></span>
<span class="line"><span>        // 执行业务逻辑</span></span>
<span class="line"><span>    } finally {</span></span>
<span class="line"><span>        lock.unlock();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>两者的主要区别：</p><ul><li><code>lock()</code>：如果获取不到锁，通常会持续等待。</li><li><code>tryLock()</code>：尝试获取锁，如果当前无法获取，则返回 <code>false</code>。</li></ul><p>还可以指定等待时间和锁的租约时间：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>boolean success = lock.tryLock(</span></span>
<span class="line"><span>        5,</span></span>
<span class="line"><span>        10,</span></span>
<span class="line"><span>        TimeUnit.SECONDS</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>这里：</p><ul><li>第一个参数 <code>5</code>：最多等待 5 秒获取锁。</li><li>第二个参数 <code>10</code>：获取锁后，10 秒后自动释放。</li></ul><p>如果在 5 秒内获取不到锁，返回 <code>false</code>。</p><p>需要特别区分：显式指定 <code>leaseTime</code> 后，锁会在指定时间后自动释放，不再依赖默认的看门狗续期机制。因此，租约时间应当结合业务执行时间谨慎设置。</p><h3 id="_5-unlock-释放锁" tabindex="-1">5. unlock()：释放锁 <a class="header-anchor" href="#_5-unlock-释放锁" aria-label="Permalink to &quot;5. unlock()：释放锁&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lock.unlock();</span></span></code></pre></div><p>业务执行完成后，需要释放锁，让其他等待的线程有机会获得锁。</p><p>这里不能简单地执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DEL lock:coupon:1001</span></span></code></pre></div><p>因为可能出现以下情况：</p><ol><li>实例 A 获取锁。</li><li>A 的锁到期。</li><li>实例 B 成功获取同一把锁。</li><li>实例 A 恢复执行，并尝试释放锁。</li></ol><p>如果 A 直接删除 Key，就可能误删 B 持有的锁。</p><p>因此，Redisson 在释放锁时会校验持有者身份，并结合重入计数判断是否应该真正删除锁。</p><p>如果当前线程并不是锁的持有者，调用 <code>unlock()</code> 会抛出 <code>IllegalMonitorStateException</code>。</p><p>这<strong>也是为什么通常将 <code>unlock()</code> 放在 <code>finally</code> 中，保证业务代码正常结束或抛出异常时，都能执行释放操作。</strong></p><h2 id="五、redisson-的-rlock-有什么特别之处" tabindex="-1">五、Redisson 的 RLock 有什么特别之处？ <a class="header-anchor" href="#五、redisson-的-rlock-有什么特别之处" aria-label="Permalink to &quot;五、Redisson 的 RLock 有什么特别之处？&quot;">​</a></h2><p>相比于自己使用 <code>SET NX EX</code> 实现的简单锁，Redisson 的 <code>RLock</code> 还提供了几个重要能力。</p><h3 id="_1-可重入性" tabindex="-1">1. 可重入性 <a class="header-anchor" href="#_1-可重入性" aria-label="Permalink to &quot;1. 可重入性&quot;">​</a></h3><p>可重入锁意味着同一个线程可以多次获得同一把锁，而不会因为自己已经持有锁而发生死锁。</p><p>例如：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> methodA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    lock.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        methodB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">finally</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        lock.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unlock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> methodB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    lock.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        // 执行业务逻辑</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">finally</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        lock.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unlock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>如果 <code>methodA()</code> 和 <code>methodB()</code> 使用的是同一把锁，并且由同一个线程执行，那么第二次获取锁时不会被自己阻塞，而是增加重入计数。</p><p>对应地，释放锁时会减少重入计数。</p><p>只有当重入计数归零时，锁才真正释放。</p><h3 id="_2-看门狗机制-watchdog" tabindex="-1">2. 看门狗机制（Watchdog） <a class="header-anchor" href="#_2-看门狗机制-watchdog" aria-label="Permalink to &quot;2. 看门狗机制（Watchdog）&quot;">​</a></h3><p>前面提到，分布式锁需要设置过期时间，避免应用宕机后锁一直无法释放。</p><p>但固定租约时间也存在问题：业务执行时间可能超过预期。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实例 A 获取锁</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>业务执行需要 40 秒</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>原定锁有效期只有 30 秒</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>锁提前过期，其他实例可能获得锁</span></span></code></pre></div><p>Redisson 为此提供了看门狗机制。</p><p>当使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lock.lock();</span></span></code></pre></div><p>且没有显式指定租约时间时，Redisson 会在锁持有期间定期延长锁的过期时间。</p><p>默认看门狗超时时间通常为 30 秒，可以通过 <code>Config.lockWatchdogTimeout</code> 配置。</p><p>只要持锁客户端仍然正常运行，且对应线程仍持有锁，看门狗就会持续续期。</p><p>当业务执行完成并释放锁后，续期也会停止。</p><p>这样可以降低业务执行时间超过预设租约时间而导致锁提前释放的风险。</p><p>注意：看门狗不能保证所有故障场景下的互斥。例如，长时间 JVM 停顿或 Redis 故障切换仍可能带来风险。因此，涉及严格业务一致性的场景，还需要结合数据库约束、幂等性或 fencing token 等机制设计。</p><h2 id="六、结合-onecoupon-理解分布式锁如何解决缓存击穿" tabindex="-1">六、结合 oneCoupon：理解分布式锁如何解决缓存击穿 <a class="header-anchor" href="#六、结合-onecoupon-理解分布式锁如何解决缓存击穿" aria-label="Permalink to &quot;六、结合 oneCoupon：理解分布式锁如何解决缓存击穿&quot;">​</a></h2><p>现在回到我们一直在研究的优惠券模板查询方法。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RLock lock = redissonClient.getLock(</span></span>
<span class="line"><span>        String.format(</span></span>
<span class="line"><span>                EngineRedisConstant.LOCK_COUPON_TEMPLATE_KEY,</span></span>
<span class="line"><span>                requestParam.getCouponTemplateId()</span></span>
<span class="line"><span>        )</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>lock.lock();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>try {</span></span>
<span class="line"><span>    // 双重检查空值缓存</span></span>
<span class="line"><span>    hasKeyFlag =</span></span>
<span class="line"><span>            stringRedisTemplate.hasKey(</span></span>
<span class="line"><span>                    couponTemplateIsNullCacheKey</span></span>
<span class="line"><span>            );</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (hasKeyFlag) {</span></span>
<span class="line"><span>        throw new ClientException(&quot;优惠券模板不存在&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 双重检查正常缓存</span></span>
<span class="line"><span>    couponTemplateCacheMap =</span></span>
<span class="line"><span>            stringRedisTemplate.opsForHash()</span></span>
<span class="line"><span>                    .entries(couponTemplateCacheKey);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (MapUtil.isEmpty(couponTemplateCacheMap)) {</span></span>
<span class="line"><span>        // 查询 MySQL</span></span>
<span class="line"><span>        // 写入正常缓存或空值缓存</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>} finally {</span></span>
<span class="line"><span>    lock.unlock();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里的分布式锁主要用于解决缓存击穿问题。</p><p>假设优惠券模板 <code>1001</code> 是一个热门模板，其缓存突然过期，同时有大量请求到来。</p><p>如果没有锁，多个请求可能同时发现缓存不存在，然后全部查询 MySQL，造成数据库压力。</p><p>使用分布式锁后：</p><ol><li>多个请求同时发现正常缓存不存在。</li><li>它们竞争 <code>lock:template:1001</code>。</li><li>只有一个请求成功获取锁，负责查询数据库和重建缓存。</li><li>其他请求等待。</li><li>第一个请求完成缓存重建并释放锁。</li><li>后续请求获取锁后，再次检查缓存，发现已经存在，就不需要重复查询数据库。</li></ol><p>这里还有一个重要设计：<strong>为什么获取锁后还要再次检查缓存？</strong></p><p>因为请求在等待锁的过程中，其他线程可能已经完成了缓存重建。</p><p>如果不进行第二次检查，即使缓存已经存在，后续请求仍可能再次查询数据库，导致重复工作。</p><p>因此，双重检查与分布式锁需要配合使用。</p><p>这就是 oneCoupon 中缓存击穿治理的基本思路。</p><h2 id="七、使用分布式锁还需要注意什么" tabindex="-1">七、使用分布式锁还需要注意什么？ <a class="header-anchor" href="#七、使用分布式锁还需要注意什么" aria-label="Permalink to &quot;七、使用分布式锁还需要注意什么？&quot;">​</a></h2><h3 id="_1-分布式锁不等于业务幂等" tabindex="-1">1. 分布式锁不等于业务幂等 <a class="header-anchor" href="#_1-分布式锁不等于业务幂等" aria-label="Permalink to &quot;1. 分布式锁不等于业务幂等&quot;">​</a></h3><p>锁主要用于控制并发访问，并不能自动保证业务操作只执行一次。</p><p>例如，用户重复提交优惠券领取请求，即使两次请求没有同时执行，也可能先后成功执行。</p><p>因此，业务还需要结合唯一请求 ID、数据库唯一索引、状态校验等机制实现幂等性。</p><h3 id="_2-分布式锁不代表绝对安全" tabindex="-1">2. 分布式锁不代表绝对安全 <a class="header-anchor" href="#_2-分布式锁不代表绝对安全" aria-label="Permalink to &quot;2. 分布式锁不代表绝对安全&quot;">​</a></h3><p>Redisson 可以帮助我们管理锁的获取、续期和释放，但 Redis 主从异步复制、故障切换等场景仍可能影响锁的互斥保证。</p><p>对于普通缓存重建，这类方案通常具有较好的实用性；对于资金扣减、库存最终一致性等关键业务，不能仅依赖分布式锁，还需要数据库条件更新、唯一约束、幂等处理等机制。</p><h3 id="_3-锁的粒度要合理" tabindex="-1">3. 锁的粒度要合理 <a class="header-anchor" href="#_3-锁的粒度要合理" aria-label="Permalink to &quot;3. 锁的粒度要合理&quot;">​</a></h3><p>oneCoupon 使用优惠券模板 ID 作为锁 Key 的一部分：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lock:template:1001</span></span>
<span class="line"><span>lock:template:1002</span></span>
<span class="line"><span>lock:template:1003</span></span></code></pre></div><p>这样不同模板之间可以并行处理，只有访问同一个模板的请求才会竞争同一把锁。</p><p>这属于按业务资源划分锁粒度，可以减少不必要的并发阻塞。</p><h2 id="八、总结" tabindex="-1">八、总结 <a class="header-anchor" href="#八、总结" aria-label="Permalink to &quot;八、总结&quot;">​</a></h2><p>Redis 能够实现分布式锁，核心在于它为多个应用实例提供了共享的存储空间，并且提供了具有原子执行语义的操作，例如 <code>SET NX EX</code>。</p><p>Redisson 则在 Redis 的基础上进一步封装了分布式可重入锁 <code>RLock</code>，提供锁竞争、阻塞等待、可重入、持有者校验、自动续期和释放通知等能力。</p><p>通过 oneCoupon 项目的实践，我们可以看到分布式锁并不是孤立存在的技术，而是缓存治理的一部分：</p><ul><li>Redis Hash 保存优惠券模板缓存。</li><li>空值缓存缓解缓存穿透。</li><li>Redisson 分布式锁协调缓存重建。</li><li>双重检查避免重复查询数据库。</li><li>Lua 脚本保证多步 Redis 操作的原子执行。</li></ul><p><strong>学习分布式锁，真正需要掌握的不只是</strong> <code>**lock()**</code> <strong>和</strong> <code>**unlock()**</code> <strong>两个方法，而是理解多个应用实例如何围绕共享资源实现并发协调，以及锁在异常、超时和恢复场景下可能出现的问题。</strong></p><h3 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h3><ol><li><a href="https://redisson.org/docs/data-and-services/locks-and-synchronizers/" target="_blank" rel="noreferrer">Redisson 官方文档：Locks and Synchronizers</a></li><li><a href="https://github.com/redisson/redisson/blob/master/redisson/src/main/java/org/redisson/RedissonLock.java" target="_blank" rel="noreferrer">Redisson RLock 源码</a></li><li><a href="https://redis.io/docs/latest/commands/set/" target="_blank" rel="noreferrer">Redis 官方文档：SET 命令</a></li><li><a href="https://redis.io/docs/latest/develop/programmability/eval-intro/" target="_blank" rel="noreferrer">Redis 官方文档：Lua 脚本</a></li></ol>`,157)])])}const g=a(i,[["render",l]]);export{k as __pageData,g as default};
